//! 🧪️ Actual donated mixed SELECT controls keep constructor and source-reference branches distinct.
use super::*;
use semio_framework_plugin::{AppRenderOperationContext,ChildContentView};
use semio_framework_ui_contract::{Component,OriginalBuiltTreeRetirement};
use semio_s_artifact_stdio_ifc_4_model::standards::v4::subsets::any::schema::snapshot::{IfcEntity,IfcComplexType,IfcTypedValue};
fn mixed_value(row:&serde_json::Value)->IfcValue{match row["kind"].as_str().unwrap(){"unset"=>IfcValue::Unset,"reference"=>IfcValue::Reference(row["value"].as_str().unwrap().parse().unwrap()),"real"=>IfcValue::Real(f64::from_bits(row["value"]["bits"].as_str().unwrap().parse().unwrap())),"aggregate"=>IfcValue::Aggregate(row["value"].as_array().unwrap().iter().map(mixed_value).collect()),"typedValue"=>IfcValue::TypedValue(IfcTypedValue{name:row["value"]["name"].as_str().unwrap().into(),items:row["value"]["items"].as_array().unwrap().iter().map(mixed_value).collect()}),_=>panic!("closed source fixture")}}
#[test]
fn donated_mixed_select_controller_preserves_exact_branch_controls_and_original_source_retirement(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../🔎️details/🧪️tests/type-mixed-select-input.json")).unwrap();for row in law["cases"].as_array().unwrap(){let snapshot=std::sync::Arc::new(IfcSnapshot{entities:law["source"]["entities"].as_array().unwrap().iter().map(|entity|IfcEntity{id:entity["id"].as_str().unwrap().parse().unwrap(),name:entity["name"].as_str().unwrap().into(),args:entity["args"].as_array().unwrap().iter().map(mixed_value).collect(),complex:entity["complex"].as_array().unwrap().iter().map(|part|IfcComplexType{name:part["name"].as_str().unwrap().into(),args:part["args"].as_array().unwrap().iter().map(mixed_value).collect()}).collect()}).collect(),..Default::default()});let history=semio_framework_plugin::HistoryView::empty();let view=staged_view();let operation=AppRenderOperationContext{app_instance_id:17,base_revision:semio_framework_job::RevisionId(0),generation:semio_framework_job::Generation(1),canonical_base_revision:[0;32],mounted_policy:semio_framework_plugin::app_testing::artifact_app_laws::fixture_mounted_policy()};let doc=semio_framework_async::poll::resolve_ready(ArtifactView::with_render_context(snapshot.as_ref(),&history,ChildContentView::EMPTY,operation,"actual-mixed-source",None));let mut caller=OriginalWorkFixture::new();let mut work=caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::begin_render_work(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,cx)).unwrap().unwrap();let rows=if row["input"].is_null(){serde_json::json!([])}else{serde_json::json!([{"index":law["index"],"value":row["input"]}])};let mut request=staged_request(&serde_json::json!({"path":"/entities/0","value":{"$ifcType":law["entity"],"$ifcInputs":rows}}));request.token.action=editing::SET_SNAPSHOT_VALUE_ACTION_ID.into();let mut donor=Some(request);for _ in 0..16{if caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::receive_render_work_request(&mut work,&mut donor,&view,cx)).unwrap().is_some(){break;}}assert!(donor.is_none());let mut output=None;for _ in 0..1000000{match caller.work_turn(staged_grant(),1000,|cx|Ok(work.render(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,&snapshot,&doc,&view,cx))).unwrap(){Ok(Some(tree))=>{output=Some(tree);break;},Ok(None)=>{},Err(_)=>panic!("mixed SELECT draft stays editable: {}",row["id"])}}let tree=output.unwrap();let Component::Extension(status)=&tree.root.children.get(0).unwrap().component else{panic!("original status")};assert_eq!(serde_json::to_value(&status.props).unwrap()["ready"],row["ready"]);let fields=tree.root.children.iter().skip(1).collect::<Vec<_>>();assert_eq!(fields.len(),if row["input"].is_null(){1}else{2});let node=fields[0].children.get(0).unwrap();let Component::Select(select)=&node.component else{panic!("complete mixed member choices")};assert_eq!(select.items.len(),2);assert_eq!(select.value.as_ref(),if row["input"].is_null(){""}else if row["input"]["kind"]=="reference"{"IFCVECTOR"}else{"IFCPOSITIVELENGTHMEASURE"});assert!(!node.bindings.is_empty());if !row["input"].is_null(){let node=fields[1].children.get(0).unwrap();let Component::Input(input)=&node.component else{panic!("actual scalar or ordinary reference input")};let raw=if row["input"]["kind"]=="reference"{row["input"]["value"].as_str().unwrap()}else{row["input"]["value"]["items"].as_array().unwrap().first().map(|value|value["value"]["bits"].as_str().unwrap()).unwrap_or("")};assert_eq!(input.value.as_ref(),raw);assert!(!node.bindings.is_empty());}let mut close=OriginalBuiltTreeRetirement::new(tree.root);for _ in 0..1000000{if close.terminal_is_empty(){break;}caller.turn(staged_grant(),|cx|cx.with_original_retirement(|cx|{let demand=close.next_demand(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|close.step(grant))?;Ok(())})).unwrap();}assert!(close.terminal_is_empty());caller.cancel().cancel_now();retire_staged(&mut caller,&mut Some(work));assert_eq!(std::sync::Arc::strong_count(&snapshot),1);caller.finish();}
}
